CREATE TABLE `expense_daily_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `record_date` date NOT NULL COMMENT '日期',
  `person_name` varchar(50) NOT NULL COMMENT '人员姓名',
  `person_type` varchar(20) NOT NULL DEFAULT '工程师' COMMENT '人员类型: 工程师/驾驶员',
  `normal_hours` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '正常工时',
  `overtime_hours` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '加班工时',
  `work_hours` decimal(6,1) NOT NULL DEFAULT '0.0' COMMENT '总工时(自动计算)',
  `is_overtime` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否加班',
  `travel_status` varchar(20) DEFAULT '未出差' COMMENT '出差状态',
  `advance_payment` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '垫付金额',
  `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '合计金额',
  `approval_status` varchar(20) DEFAULT '待审批' COMMENT '审批状态',
  `source_id` int DEFAULT NULL COMMENT '来源考勤记录ID',
  `source_type` varchar(20) DEFAULT NULL COMMENT '来源类型: engineer/driver',
  `supplier` varchar(50) DEFAULT NULL COMMENT '供应商（从人员绑定同步）',
  `remark` longtext COMMENT '备注',
  `project_id` bigint NOT NULL COMMENT '所属项目',
  `test_order_id` bigint DEFAULT NULL COMMENT '所属试验单号',
  `source` varchar(20) NOT NULL DEFAULT '手动' COMMENT '数据来源: 手动/飞书',
  PRIMARY KEY (`id`),
  KEY `fk_expense__expense__fd910338` (`project_id`),
  KEY `fk_expense__expense__511ac450` (`test_order_id`),
  KEY `idx_expense_dai_created_81f4ae` (`created_at`),
  KEY `idx_expense_dai_updated_d49dc6` (`updated_at`),
  KEY `idx_expense_dai_record__2ce7cc` (`record_date`),
  CONSTRAINT `fk_expense__expense__511ac450` FOREIGN KEY (`test_order_id`) REFERENCES `expense_test_order` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_expense__expense__fd910338` FOREIGN KEY (`project_id`) REFERENCES `expense_project` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=24177 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='每日费用记录';
